

















import { BaseVueComponent, Component } from "sunway-vue";
import TreePlusImg from "@/com/sunwayworld/components/img/TreePlusImg.vue";
import TreeMinusImg from "@/com/sunwayworld/components/img/TreeMinusImg.vue";

interface Props {
    expand?: boolean;
    title?: string;
}

@Component({
    components: { TreePlusImg, TreeMinusImg }
})
export default class CollapsePanel extends BaseVueComponent<Props> {
    private switchIconStyle: SvgImgOptions = {
        color: "#444",
        width: "12px",
        height: "12px"
    };

    private expand: boolean = Gikam.isEmpty(this.props.expand) ? true : (this.props.expand as boolean);

    get title() {
        return this.props.title;
    }

    private toggle() {
        this.expand = !this.expand;
    }
}
