

























































import { Component, BaseVueComponent, State, Action } from "sunway-vue";
import ToolbarButton from "./ToolbarButton.vue";
import SaveImg from "@/com/sunwayworld/components/img/SaveImg.vue";
import PlusImg from "@/com/sunwayworld/components/img/PlusImg.vue";
import ForkImg from "@/com/sunwayworld/components/img/ForkImg.vue";
import FieldsTree from "./FieldsTree.vue";
import MoveDownImg from "@/com/sunwayworld/components/img/MoveDownImg.vue";
import MoveUpImg from "@/com/sunwayworld/components/img/MoveUpImg.vue";
import FieldSettingPanle from "../field/FieldSettingPanel.vue";

@Component({
    components: { ToolbarButton, SaveImg, FieldsTree, PlusImg, ForkImg, MoveDownImg, MoveUpImg, FieldSettingPanle }
})
export default class FieldsDesignContainer extends BaseVueComponent<GeneralObject> {
    @State("comp")
    private formInstance!: Gikam.component.Form;

    @Action
    private moveFieldUp!: Function;

    @Action
    private moveFieldDown!: Function;

    @Action
    private insertField!: Function;

    @Action
    private removeField!: Function;
}
