










import { BaseVueComponent, Component, Action } from "sunway-vue";
import TreeRootNodeImg from "@/com/sunwayworld/components/img/TreeRootNodeImg.vue";
import { FormField, FormFieldVue } from "../../interface/FormInterface";
import TreeMinusImg from "@/com/sunwayworld/components/img/TreeMinusImg.vue";
import TreePlusImg from "@/com/sunwayworld/components/img/TreePlusImg.vue";

interface Props {
    field: FormField;
}

@Component({
    components: {
        TreeMinusImg,
        TreePlusImg,
        TreeRootNodeImg
    }
})
export default class FieldTreeNode extends BaseVueComponent<Props> {
    field: FormFieldVue = this.props.field;

    @Action
    activeField!: (field: FormField) => void;

    nodeClickHandle() {
        this.$set(this.field, "active", true);
        this.activeField(this.field);
    }

    getActiveNodeClass() {
        return {};
    }

    propI18N(text: string): string {
        return Gikam.propI18N(text);
    }

    private mounted() {
        if (this.field.active) {
            this.nodeClickHandle();
        }
    }
}
