



























































import { Component, State, BaseVueComponent, Mutation, Watch } from "sunway-vue";
import TreeRootNodeImg from "@/com/sunwayworld/components/img/TreeRootNodeImg.vue";
import FieldTreeNode from "./FieldTreeNode.vue";
import TreeMinusImg from "@/com/sunwayworld/components/img/TreeMinusImg.vue";
import TreePlusImg from "@/com/sunwayworld/components/img/TreePlusImg.vue";

interface Props {
    title: string;
    fields: Gikam.component.FormPanel[];
}

@Component({
    components: {
        TreeRootNodeImg,
        FieldTreeNode,
        TreeMinusImg,
        TreePlusImg
    }
})
export default class FieldsTree extends BaseVueComponent<Props> {
    private expand = true;

    @State
    formInstance!: Gikam.component.Form;

    @State
    tempOptions!: Gikam.component.FormOptions;

    @Mutation
    setFormSetting!: () => void;

    get options(): Gikam.component.FormOptions {
        const options = this.tempOptions;
        if (options.panels.length) {
            options.panels.forEach((panel, index) => {
                if (index === 0) {
                    this.$set(panel, "expand", true);
                } else {
                    this.$set(panel, "expand", false);
                }
            });
        }
        return options;
    }

    get id(): string {
        return this.formInstance.options.id || "";
    }

    switchClickHandle(): void {
        this.expand = !this.expand;
    }

    switchNodeClickHandle(panel: Gikam.component.FormPanel): void {
        panel.expand = !panel.expand;
    }
}
