

































import { Component, BaseVueComponent, State, Mutation, Action } from "sunway-vue";
import CollapsePanel from "../collapsePanel/CollapsePanel.vue";
import TextEditor from "@/com/sunwayworld/components/editor/TextEditor.vue";
import NumberEditor from "@/com/sunwayworld/components/editor/NumberEditor.vue";
import ChooseEditor from "@/com/sunwayworld/components/editor/ChooseEditor.vue";
import SelectEditor from "@/com/sunwayworld/components/editor/select/SelectEditor.vue";
import { FormField, FieldEditor, FieldEvent, FieldChangeOption } from "../../interface/FormInterface";

type ValueType = string | number | null | undefined;

@Component({
    components: { CollapsePanel, TextEditor, NumberEditor, ChooseEditor, SelectEditor }
})
export default class FieldSettingPanle extends BaseVueComponent<GeneralObject> {
    @State
    private activeField?: FormField & Record<string, string>;

    @State("activeFieldEditorAttrs")
    private attributes!: FieldEditor[];

    @State("activeFieldEditorEvents")
    private events!: FieldEvent[];

    @Action
    private updateFieldAttr!: (attr: FieldChangeOption) => void;

    @Mutation
    private updateFormDate!: Function;

    saveChange(value: ValueType, oldValue: ValueType, attribute: string) {
        this.updateFormDate({ value, oldValue, attribute });
    }

    private getAttributeKey(attribute: FieldEditor) {
        if (!this.activeField) {
            return;
        }
        return this.activeField.field + attribute.attribute;
    }
}
