

















import { Vue, Component, State, Action } from "sunway-vue";
import FieldsDesginContainer from "./desginContainer/FieldsDesignContainer.vue";

@Component({
    components: {
        FieldsDesginContainer
    }
})
export default class FieldsDesignBox extends Vue {
    @Action
    private updateFormFields!: () => void;

    @State
    formInstance!: Gikam.component.Form;

    private async confirmHandle() {
        await this.updateFormFields();
        this.$emit("confirmUpdateFields", this.formInstance);
        this.cancelHandle();
    }

    @State
    private comp!: Gikam.component.Form;

    private cancelHandle(): void {
        this.$destroy();
        Gikam.removeDom(this.$el);
    }
}
